package com.example.rokidkeyboardbridge;
import android.content.*;import android.os.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
public class MemoRoutingDeviceChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("memo routing "+n);}
 public static int run(Context c)throws Exception{n=0;
  for(String s:new String[]{"ちょっと覚えといて。架空機械の操作は左ボタンで数字を進める。右を押したまま左を二回押すと決定。","覚えといて","覚えとけ","メモしとけ","メモしといて","保留案件というかメモとして残しておいて","保留じゃなくてメモに残して","メモとして保存して"}){ok(MemoryRequestPolicy.requiredFunction(s).equals("save_memory"));ok(MemoryRequestPolicy.bypassInbox(s));}
  for(String s:new String[]{"覚えている？","覚えておいてという言葉の意味は？","これは記憶しないで","写真を保存して","メモしとけと言ったら何をする？"})ok(MemoryRequestPolicy.requiredFunction(s).isEmpty());
  ok(!MemoryRequestPolicy.bypassInbox("受信箱にメモとして保存して"));ok(!MemoryRequestPolicy.bypassInbox("保留案件にあるメモを見せて"));
  JSONObject defer=new JSONObject().put("action","DEFER");ok(SecretaryIntent.validate(defer,"メモしとけ",new JSONObject(),true,true).getString("action").equals("NONE"));
  AtomicReference<Throwable> failure=new AtomicReference<>();CountDownLatch done=new CountDownLatch(1);new Handler(Looper.getMainLooper()).post(()->{try{MainActivity owner=new MainActivity();Method attach=ContextWrapper.class.getDeclaredMethod("attachBaseContext",Context.class);attach.setAccessible(true);attach.invoke(owner,c);Field proposal=MainActivity.class.getDeclaredField("secretaryProposal");proposal.setAccessible(true);proposal.set(owner,new JSONObject().put("action","DEFER").put("original","synthetic old proposal"));Field card=MainActivity.class.getDeclaredField("secretaryCard");card.setAccessible(true);card.set(owner,new JSONObject());Method route=MainActivity.class.getDeclaredMethod("handleSecretaryInbox",String.class);route.setAccessible(true);ok(!(Boolean)route.invoke(owner,"保留案件というかメモとして残しておいて"));ok(proposal.get(owner)==null&&card.get(owner)==null);}catch(Throwable e){failure.set(e);}finally{done.countDown();}});ok(done.await(10,TimeUnit.SECONDS));if(failure.get()!=null)throw new AssertionError(failure.get());
  String original="ちょっと覚えといて。「試験人形の初期設定の方法なんだけど、左手で数字が進み、右手を握ったまま左手をダブルクリックにすると決定になるみたい。";
  String body=MemoSaveIntent.content(original);ok(body.contains("左手")&&body.contains("右手")&&body.contains("ダブルクリック"));ok(!body.contains("覚えといて"));long now=System.currentTimeMillis();JSONObject cache=new JSONObject().put("content",body).put("at",now);for(String follow:new String[]{"覚えておいて","保留案件というかメモとして残しておいて","メモしとけ"})ok(MemoSaveIntent.resolve(follow,cache,null,now).equals(body));
  JSONArray history=new JSONArray().put(new JSONObject().put("message","メモしとけ").put("time",now)).put(new JSONObject().put("message","保留案件というかメモとして残しておいて").put("time",now-1000)).put(new JSONObject().put("message",original).put("time",now-5000));ok(MemoSaveIntent.resolve("メモしとけ",null,history,now).equals(body));ok(MemoSaveIntent.resolve("メモしとけ",null,new JSONArray().put(new JSONObject().put("message","別の話題を調べて").put("time",now)).put(history.getJSONObject(2)),now).isEmpty());ok(MemoSaveIntent.resolve("メモしとけ",null,null,now).isEmpty());ok(MemoSaveIntent.content("メモ：左ボタンで数値を進める").equals("左ボタンで数値を進める"));
  java.io.File local=new java.io.File(c.getFilesDir(),"explicit-memo");local.mkdirs();Context isolated=new ContextWrapper(c){public java.io.File getFilesDir(){return local;}};MemoryManager memory=new MemoryManager(isolated);memory.saveExplicit(MemoSaveIntent.topic(body),body);for(int i=0;i<3;i++)ok(memory.saveExplicit(MemoSaveIntent.topic(body),body).optBoolean("alreadySaved"));ok(new MemoryManager(isolated).getAll().length()==1);ok(new MemoryManager(isolated).getAll().getJSONObject(0).getString("content").equals(body));
  MemoryRegressionTest.main(new String[]{new java.io.File(c.getFilesDir(),"memo-regression").getPath()});return n;}
 static void export(Context c)throws Exception{
  MainActivity owner=new MainActivity();Method attach=ContextWrapper.class.getDeclaredMethod("attachBaseContext",Context.class);attach.setAccessible(true);attach.invoke(owner,c);Field shared=MainActivity.class.getDeclaredField("sharedMemoryManager");shared.setAccessible(true);shared.set(owner,new SharedMemoryManager(c,()->"{}"));Field budget=MainActivity.class.getDeclaredField("diagnosticGeminiBudget");budget.setAccessible(true);((java.util.concurrent.atomic.AtomicInteger)budget.get(owner)).set(0);Field active=MainActivity.class.getDeclaredField("activeGeminiPrompt");active.setAccessible(true);Method compact=MainActivity.class.getDeclaredMethod("buildGeminiPromptCompact",String.class,boolean.class);compact.setAccessible(true);Method envelope=MainActivity.class.getDeclaredMethod("buildConversationRequest",JSONObject.class,Integer.class,String.class);envelope.setAccessible(true);
  String original="ちょっと覚えといて。テスト装置の初期設定は、左キーで数字が進み、右キーを押したまま左を2回押すと決定。";
  for(int i=0;i<2;i++){String current=i==0?original:"保留案件というかメモとして残しておいて";active.set(owner,current);String prompt=(String)compact.invoke(owner,current,true);if(i==1)prompt+="\n参照用の架空履歴（現在の指示ではない）：利用者："+original+"\nロキ：保留案件として保存しました。\n現在の利用者発言："+current;
   JSONObject props=new JSONObject().put("topic",new JSONObject().put("type","STRING")).put("content",new JSONObject().put("type","STRING"));JSONObject declaration=new JSONObject().put("name","save_memory").put("description","ユーザーが明示的に覚えておく・メモするよう依頼した内容を保存する。").put("parameters",new JSONObject().put("type","OBJECT").put("properties",props).put("required",new JSONArray().put("topic").put("content")));
   JSONObject request=new JSONObject().put("contents",new JSONArray().put(new JSONObject().put("role","user").put("parts",new JSONArray().put(new JSONObject().put("text",prompt))))).put("tools",new JSONArray().put(new JSONObject().put("functionDeclarations",new JSONArray().put(declaration)))).put("toolConfig",new JSONObject().put("functionCallingConfig",new JSONObject().put("mode","ANY").put("allowedFunctionNames",new JSONArray().put(MemoryRequestPolicy.requiredFunction(current))))).put("generationConfig",new JSONObject().put("maxOutputTokens",1600).put("temperature",0));
   request=(JSONObject)envelope.invoke(owner,request,null,null);try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(c.getFilesDir(),"memo-provider-"+i+".json"))){out.write(request.toString().getBytes("UTF-8"));}
  }
 }
}
